import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader, Dataset

# Create working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")


# Synthetic dataset creation
class ReviewDataset(Dataset):
    def __init__(self, num_samples=1000, distribution_type=1):
        if distribution_type == 1:
            self.data = np.random.rand(num_samples, 5)  # uniform distribution
        elif distribution_type == 2:
            self.data = np.random.normal(
                loc=0.5, scale=0.2, size=(num_samples, 5)
            ).clip(
                0, 1
            )  # normal distribution
        elif distribution_type == 3:
            self.data = np.random.beta(
                a=2, b=5, size=(num_samples, 5)
            )  # beta distribution
        else:
            self.data = np.random.rand(num_samples, 5)  # default to uniform
        self.labels = (
            self.data.sum(axis=1) + np.random.rand(num_samples)
        ) / 6  # RQI score

    def __len__(self):
        return len(self.labels)

    def __getitem__(self, idx):
        return {
            "features": torch.tensor(self.data[idx], dtype=torch.float).to(device),
            "label": torch.tensor(self.labels[idx], dtype=torch.float).to(device),
        }


# Model definition with customizable activation function
class RQIModel(nn.Module):
    def __init__(self, activation_fn):
        super(RQIModel, self).__init__()
        self.fc1 = nn.Linear(5, 10)
        self.fc2 = nn.Linear(10, 1)
        self.activation_fn = activation_fn

    def forward(self, x):
        x = self.activation_fn(self.fc1(x))
        x = self.fc2(x)
        return x


# Prepare datasets
datasets = {
    "Uniform": ReviewDataset(distribution_type=1),
    "Normal": ReviewDataset(distribution_type=2),
    "Beta": ReviewDataset(distribution_type=3),
}

# Experiment data storage
experiment_data = {"multi_dataset_performance": {}}

activation_functions = {
    "ReLU": nn.ReLU(),
    "LeakyReLU": nn.LeakyReLU(0.01),
    "ELU": nn.ELU(),
    "Tanh": nn.Tanh(),
}

for dataset_name, dataset in datasets.items():
    print(f"Evaluating dataset: {dataset_name}")
    train_size = int(0.8 * len(dataset))
    val_size = len(dataset) - train_size
    train_data, val_data = torch.utils.data.random_split(
        dataset, [train_size, val_size]
    )
    train_loader = DataLoader(train_data, batch_size=32, shuffle=True)
    val_loader = DataLoader(val_data, batch_size=32, shuffle=False)

    experiment_data["multi_dataset_performance"][dataset_name] = {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
    }

    for act_name, act_func in activation_functions.items():
        print(f"Training with activation function: {act_name}")
        model = RQIModel(act_func).to(device)
        criterion = nn.MSELoss()
        optimizer = optim.Adam(model.parameters(), lr=0.001)

        for epoch in range(100):
            model.train()
            train_loss = 0.0
            for batch in train_loader:
                batch = {
                    k: v.to(device)
                    for k, v in batch.items()
                    if isinstance(v, torch.Tensor)
                }
                features = batch["features"]
                labels = batch["label"]
                optimizer.zero_grad()
                outputs = model(features).squeeze()
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()
                train_loss += loss.item()

            train_loss /= len(train_loader)
            experiment_data["multi_dataset_performance"][dataset_name]["losses"][
                "train"
            ].append(train_loss)
            print(f"Epoch {epoch}: training_loss = {train_loss:.4f}")

            # Validation loop
            model.eval()
            val_loss = 0.0
            with torch.no_grad():
                for batch in val_loader:
                    batch = {
                        k: v.to(device)
                        for k, v in batch.items()
                        if isinstance(v, torch.Tensor)
                    }
                    features = batch["features"]
                    labels = batch["label"]
                    outputs = model(features).squeeze()
                    loss = criterion(outputs, labels)
                    val_loss += loss.item()

            val_loss /= len(val_loader)
            experiment_data["multi_dataset_performance"][dataset_name]["losses"][
                "val"
            ].append(val_loss)
            print(f"Epoch {epoch}: validation_loss = {val_loss:.4f}")

# Save experiment data
np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)

